// Stop playbook ⭐ CRITICAL — only playbook allowed to return decision != 'allow'.
// Loads story_goal_state, scores transcript vs acceptance_criteria, decides:
//   - all met       → allow (✅ Goal reached)
//   - some missing  → block (force loop continuation with expert observation)
//   - loop cap hit  → ask (escalate to manual review)
//
// MVP: only loop-cap guard is enforced; criterion evaluation is a stub that
// reports criteria as 'pending evaluation' (LLM-based scoring lands in next
// iteration with mid-tier model + low temperature).
const body = $input.first().json.body || $input.first().json;
if (body.event !== 'stop') {
  throw new Error(`WF_DIRIGENT_GOAL_EVALUATOR expects event=stop, got ${body.event}`);
}
return [{
  json: {
    story_id: body.story_id || null,
    session_id: body.session_id || null,
    transcript_excerpt: String(body.transcript_excerpt || '').slice(0, 4000),
    has_story: !!body.story_id
  }
}];

// Goal evaluation. MVP semantics (no LLM yet):
//   - no story_id            → allow with hint to set story
//   - loop_iterations >= max  → ask
//   - acceptance_criteria empty → allow (nothing to evaluate)
//   - otherwise               → block with expert observation that
//     criteria need explicit verification this turn
//
// Once LLM scoring lands, replace the placeholder block-text with per-
// criterion met/partial/missing with evidence quotes.
const input = $('Validate Input').first().json;
const story = $input.first().json;
const now = new Date().toISOString();

if (!input.has_story) {
  return [{
    json: {
      advisory: '📋 AISHA Dirigent: no active story — Stop allowed without evaluation.',
      decision: 'allow',
      _audit: { event: 'stop', story_id: null, session_id: input.session_id, branch: 'no_story', now }
    }
  }];
}

const gs = (story && story.success !== false) ? (story.goal_state || story) : null;
const loopIter = Number(gs?.loop_iterations ?? 0);
const loopMax = Number(gs?.loop_max ?? 12);
const ac = Array.isArray(gs?.acceptance_criteria) ? gs.acceptance_criteria : [];

if (loopIter >= loopMax) {
  return [{
    json: {
      advisory: '🛑 AISHA Goal Evaluator: autonomous loop reached cap.',
      decision: 'ask',
      reason: `Story autonomous loop reached cap (${loopMax} iterations). Please review manually before continuing.`,
      _audit: { event: 'stop', story_id: input.story_id, session_id: input.session_id, branch: 'loop_cap', loop_iter: loopIter, loop_max: loopMax, now }
    }
  }];
}

if (ac.length === 0) {
  return [{
    json: {
      advisory: '✅ AISHA Goal Evaluator: no acceptance criteria set — Stop allowed.',
      decision: 'allow',
      _audit: { event: 'stop', story_id: input.story_id, session_id: input.session_id, branch: 'no_criteria', now }
    }
  }];
}

// MVP block path — explicit criteria need verification this turn.
// Once LLM scoring lands, this becomes per-criterion met/partial/missing.
const criteriaList = ac.map((c, i) => `  ${i+1}. ${typeof c === 'string' ? c : (c.text || JSON.stringify(c))}`).join('\n');
return [{
  json: {
    advisory: '🔍 AISHA Goal Evaluator: kritéria potřebují ověření.',
    decision: 'block',
    reason: `Story má ${ac.length} acceptance criteria. Před Stop ověř, že každé je splněno, nebo přidej milestone log s důkazem:\n${criteriaList}\n\nIterace ${loopIter+1}/${loopMax}. Toto není pokyn — popřemýšlej a pokračuj.`,
    _audit: { event: 'stop', story_id: input.story_id, session_id: input.session_id, branch: 'criteria_pending', loop_iter: loopIter+1, criteria_count: ac.length, now }
  }
}];
